import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"Security & Anti-Spam","description":"","frontmatter":{},"headers":[],"relativePath":"admin/security.md","filePath":"admin/security.md"}'),o={name:"admin/security.md"};function s(n,e,l,c,d,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="security-anti-spam" tabindex="-1">Security &amp; Anti-Spam <a class="header-anchor" href="#security-anti-spam" aria-label="Permalink to &quot;Security &amp; Anti-Spam&quot;">​</a></h1><p>FOSSBilling includes enterprise-grade security features to protect your platform from automated abuse, fraudulent orders, and unauthorized access.</p><hr><h2 id="🛡️-the-anti-spam-module" tabindex="-1">🛡️ The Anti-Spam Module <a class="header-anchor" href="#🛡️-the-anti-spam-module" aria-label="Permalink to &quot;🛡️ The Anti-Spam Module&quot;">​</a></h2><p>The Anti-Spam module is designed to block malicious bots while providing a smooth experience for real users.</p><h3 id="core-protections" tabindex="-1">Core Protections <a class="header-anchor" href="#core-protections" aria-label="Permalink to &quot;Core Protections&quot;">​</a></h3><ul><li><strong>Disposable Email Blocker:</strong> Automatically blocks registration from known temporary email providers (e.g., Mailinator, 10MinuteMail).</li><li><strong>IP Reputation (StopForumSpam):</strong> Cross-references new signups against the global StopForumSpam database.</li><li><strong>Honeypot Fields:</strong> Invisible form fields that, when filled out by bots, trigger an immediate rejection of the submission.</li><li><strong>Rate Limiting:</strong> Protects every API endpoint from brute-force attacks and DDoS by limiting requests per IP address.</li></ul><h3 id="captcha-integration" tabindex="-1">Captcha Integration <a class="header-anchor" href="#captcha-integration" aria-label="Permalink to &quot;Captcha Integration&quot;">​</a></h3><p>FOSSBilling supports modern, privacy-friendly captchas:</p><ul><li><strong>Cloudflare Turnstile:</strong> Our recommended choice for invisible challenge-response.</li><li><strong>Google reCAPTCHA v3:</strong> Standard protection against automated interactions.</li></ul><hr><h2 id="🔑-api-keys" tabindex="-1">🔑 API Keys <a class="header-anchor" href="#🔑-api-keys" aria-label="Permalink to &quot;🔑 API Keys&quot;">​</a></h2><p>For developers and external integrations, FOSSBilling provides a secure API Key system.</p><h3 id="personal-api-keys" tabindex="-1">Personal API Keys <a class="header-anchor" href="#personal-api-keys" aria-label="Permalink to &quot;Personal API Keys&quot;">​</a></h3><p>Clients and Staff can generate API keys from their respective profile settings. These keys allow programmatic access to the platform without sharing passwords.</p><ul><li><strong>Auto-Rotation:</strong> Keys can be set to expire after a certain period.</li><li><strong>IP Restriction:</strong> (Optional) Lock a key to a specific IP address or CIDR range.</li><li><strong>Scoped Permissions:</strong> Keys inherit the permissions of the user who created them.</li></ul><h3 id="managing-keys-as-an-admin" tabindex="-1">Managing Keys as an Admin <a class="header-anchor" href="#managing-keys-as-an-admin" aria-label="Permalink to &quot;Managing Keys as an Admin&quot;">​</a></h3><p>Administrators can view and revoke any active API keys from the <strong>System &gt; Security &gt; API Keys</strong> section if suspicious activity is detected.</p><hr><h2 id="📝-audit-logs" tabindex="-1">📝 Audit Logs <a class="header-anchor" href="#📝-audit-logs" aria-label="Permalink to &quot;📝 Audit Logs&quot;">​</a></h2><p>The system maintains a comprehensive audit trail of all staff activities.</p><ul><li><strong>Who:</strong> The staff member who performed the action.</li><li><strong>What:</strong> The specific change made (e.g., &quot;Updated invoice #123&quot;).</li><li><strong>When:</strong> Accurate UTC timestamp.</li><li><strong>Where:</strong> The IP address and device fingerprint of the staff member.</li></ul><p>Audit logs are immutable and provide critical data for compliance and security investigations.</p>',23)])])}const u=a(o,[["render",s]]);export{h as __pageData,u as default};
